"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

const Tabs = ({ children, value, onValueChange, className, ...props }: 
  React.ComponentProps<"div"> & {
    value: string;
    onValueChange: (value: string) => void;
  }) => {
  return (
    <div className={cn(className)} {...props}>
      {children}
    </div>
  );
};

const TabsList = React.forwardRef<HTMLDivElement, React.ComponentProps<"div">>(
  ({ className, children, ...props }, ref) => {
    return (
      <div
        ref={ref}
        className={cn(
          "inline-flex h-10 items-center justify-center rounded-md bg-muted p-1 text-muted-foreground",
          className
        )}
        {...props}
      >
        {children}
      </div>
    );
  }
);
TabsList.displayName = "TabsList";

const TabsTrigger = React.forwardRef<HTMLButtonElement, 
  React.ComponentProps<"button"> & { value: string; disabled?: boolean }
>(({ className, value, disabled, children, onClick, ...props }, ref) => {
  const [activeValue, setActiveValue] = React.useState<string>("");
  
  return (
    <button
      ref={ref}
      className={cn(
        "inline-flex items-center justify-center whitespace-nowrap rounded-sm px-3 py-1.5 text-sm font-medium ring-offset-background transition-all focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50 data-[state=active]:bg-background data-[state=active]:text-foreground data-[state=active]:shadow-sm",
        className
      )}
      data-state={activeValue === value ? "active" : "inactive"}
      value={value}
      onClick={(e) => {
        onClick?.(e);
        setActiveValue(value);
      }}
      disabled={disabled}
      {...props}
    >
      {children}
    </button>
  )
});
TabsTrigger.displayName = "TabsTrigger";

const TabsContent = React.forwardRef<HTMLDivElement, 
  React.ComponentProps<"div"> & { value: string }
>(({ className, value, children, ...props }, ref) => {
  const [activeValue, setActiveValue] = React.useState<string>("");
  
  if (activeValue !== value) return null;
  
  return (
    <div
      ref={ref}
      className={cn(
        "mt-2 ring-offset-background focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2",
        className
      )}
      {...props}
    >
      {children}
    </div>
  );
});
TabsContent.displayName = "TabsContent";

export { Tabs, TabsList, TabsTrigger, TabsContent };