"use client";

import { useEffect, useState } from "react";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Loader2, RefreshCw, TrendingUp, TrendingDown, AlertTriangle, CheckCircle, XCircle, Clock } from "lucide-react";
import { cn } from "@/lib/utils";

interface Signal {
  strategy: string;
  dir: 'buy' | 'sell';
  entry: number;
  sl: number;
  tp: number;
  refLevel: number;
  reason: string;
  score: number;
  canFillNow: boolean;
  knownAt: number;
  setup?: 'A' | 'B';
  slAnchor?: number;
  slPips: number;
}

export function SignalsTable() {
  const [data, setData] = useState<{
    ok: boolean;
    pending: Signal[];
    session: string;
    syriaHour: number;
    market: any;
    daily: any;
    ai: any;
  } | null>(null);
  const [loading, setLoading] = useState(true);

  const fetchSignals = async () => {
    setLoading(true);
    try {
      const res = await fetch('/api/signals');
      const json = await res.json();
      setData(json);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchSignals();
    const interval = setInterval(fetchSignals, 30000);
    return () => clearInterval(interval);
  }, []);

  if (loading) {
    return (
      <div className="flex items-center justify-center py-8">
        <Loader2 className="h-8 w-8 animate-spin text-gold-500" />
      </div>
    );
  }

  if (!data?.ok) {
    return (
      <div className="text-center py-8 text-red-500">
        فشل تحميل الإشارات
      </div>
    );
  }

  const { pending, session, syriaHour, daily, market, ai } = data;

  const formatTime = (ts: number) => {
    return new Date(ts + 3 * 3600e3).toISOString().slice(11, 19);
  };

  const getStrategyName = (strat: string) => {
    const names: Record<string, string> = {
      A: 'إعادة اختبار كسر التجميع',
      B: 'التلاعب والاختراق الثاني',
      C: 'الأوردر بلوك المؤسسي',
      D: 'ذيول الشموع الكبرى',
      E: 'الأرقام النفسية',
      F: 'تبادل الأدوار 1H/4H',
      G: 'تبادل الأدوار 5M/15M',
      H: 'الكويزومودو 1H/4H',
      I: 'الكويزومودو 15M',
      J: 'مناطق العرض والطلب',
      K: 'فيبوناتشي متعدد الفريمات',
      L: 'فيبوناتشي جلسة آسيا',
      M: 'سحب سيولة أمريكا',
      N: 'سحب سيولة الشموع الكبيرة',
      O: 'شمعة بيبا',
      Z: 'مستويات يدوية',
    };
    return names[strat] || strat;
  };

  return (
    <div className="space-y-4">
      {/* Header with session info */}
      <div className="flex flex-wrap items-center justify-between gap-4 p-4 bg-card border rounded-lg">
        <div className="flex items-center gap-4">
          <Badge variant={session ? "default" : "destructive"} className="text-lg px-3 py-1">
            {session ? session.toUpperCase() : 'خارج الجلسات'}
          </Badge>
          <span className="text-sm text-muted-foreground">
            سوريا: {syriaHour}:00
          </span>
          {ai.available && (
            <Badge variant="secondary" className="flex items-center gap-1">
              <CheckCircle className="h-3 w-3" />
              المشرف الذكي
            </Badge>
          )}
        </div>
        <div className="flex items-center gap-4">
          <div className="flex items-center gap-2 text-sm">
            <TrendingUp className="h-4 w-4 text-green-500" />
            <span>هدف اليومي: {daily.tradesToday}/{daily.target}</span>
          </div>
          <Button variant="outline" size="sm" onClick={fetchSignals}>
            <RefreshCw className="h-4 w-4 mr-1" />
            تحديث
          </Button>
        </div>
      </div>

      {/* Market info */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-3 p-4 bg-card border rounded-lg">
        <div className="text-center">
          <div className="text-2xl font-bold text-gold-500">{market.atrPct?.toFixed(1) || '—'}%</div>
          <div className="text-xs text-muted-foreground">ATR%</div>
        </div>
        <div className="text-center">
          <div className="text-2xl font-bold">{market.rng6hPips || '—'}</div>
          <div className="text-xs text-muted-foreground">نطاق 6س (بيب)</div>
        </div>
        <div className="text-center">
          <div className="text-2xl font-bold">{market.spreadCents || '—'}</div>
          <div className="text-xs text-muted-foreground">سبريد (سنت)</div>
        </div>
        <div className="text-center">
          <div className="text-2xl font-bold">{market.trend1h || '—'}/{market.trend4h || '—'}</div>
          <div className="text-xs text-muted-foreground">ترند 1س/4س</div>
        </div>
      </div>

      {/* Signals Table */}
      <div className="bg-card border rounded-lg overflow-hidden">
        {pending.length === 0 ? (
          <div className="p-8 text-center text-muted-foreground">
            <AlertTriangle className="h-12 w-12 mx-auto mb-2 opacity-50" />
            <p>لا توجد إشارات حالياً</p>
            <p className="text-sm mt-1">سيظهر الإشارات هنا عند اكتمال شروط الاستراتيجيات</p>
          </div>
        ) : (
          <Table>
            <TableHeader>
              <TableRow className="bg-muted">
                <TableHead className="w-12 text-center">#</TableHead>
                <TableHead>الاستراتيجية</TableHead>
                <TableHead className="text-center">الاتجاه</TableHead>
                <TableHead className="text-center">الدخول</TableHead>
                <TableHead className="text-center">الوقف</TableHead>
                <TableHead className="text-center">الهدف</TableHead>
                <TableHead className="text-center">المستوى</TableHead>
                <TableHead className="text-center">الدرجة</TableHead>
                <TableHead className="text-center">الجلسة</TableHead>
                <TableHead className="text-center">الوقت</TableHead>
                <TableHead className="text-center">الحالة</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {pending.map((signal, idx) => (
                <TableRow key={`${signal.strategy}-${signal.refLevel}-${signal.knownAt}`} className="hover:bg-accent/50">
                  <TableCell className="text-center text-sm font-mono">{idx + 1}</TableCell>
                  <TableCell>
                    <div className="font-medium">{getStrategyName(signal.strategy)}</div>
                    <div className="text-xs text-muted-foreground">{signal.strategy}{signal.setup && ` (${signal.setup})`}</div>
                  </TableCell>
                  <TableCell className="text-center">
                    <Badge variant={signal.dir === 'buy' ? "success" : "destructive"} className="text-sm">
                      {signal.dir === 'buy' ? 'شراء' : 'بيع'}
                    </Badge>
                  </TableCell>
                  <TableCell className="text-center font-mono text-sm">{signal.entry.toFixed(2)}</TableCell>
                  <TableCell className="text-center font-mono text-sm text-red-500">{signal.sl.toFixed(2)}</TableCell>
                  <TableCell className="text-center font-mono text-sm text-green-500">{signal.tp.toFixed(2)}</TableCell>
                  <TableCell className="text-center font-mono text-sm text-gold-600">{signal.refLevel}</TableCell>
                  <TableCell className="text-center">
                    <div className="flex items-center justify-center gap-1">
                      <span className={cn(
                        "font-mono font-medium",
                        signal.score >= 80 && "text-green-600",
                        signal.score >= 60 && signal.score < 80 && "text-yellow-600",
                        signal.score < 60 && "text-red-600"
                      )}>
                        {Math.round(signal.score)}
                      </span>
                    </div>
                  </TableCell>
                  <TableCell className="text-center">
                    <Badge variant={signal.canFillNow ? "success" : "secondary"} className="text-xs">
                      {signal.canFillNow ? 'مفعّلة' : 'في الانتظار'}
                    </Badge>
                  </TableCell>
                  <TableCell className="text-center font-mono text-xs">
                    {formatTime(signal.knownAt)}
                  </TableCell>
                  <TableCell className="text-center">
                    {signal.canFillNow ? (
                      <Badge variant="success" className="flex items-center justify-center gap-1">
                        <CheckCircle className="h-3 w-3" />
                        جاهز
                      </Badge>
                    ) : (
                      <Badge variant="secondary" className="flex items-center justify-center gap-1">
                        <Clock className="h-3 w-3" />
                        انتظار الجلسة
                      </Badge>
                    )}
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        )}
      </div>
    </div>
  );
}